/**
 * Global directive: block repeat clicks within a cooldown window (reduces duplicate API calls).
 *
 * Default cooldown for the whole CompanySetupUI app:
 *   Set before registerPreventReclickDirective(Vue):
 *   Vue.config.preventReclickDefaultMs = 2000;
 *
 * Usage:
 *   <button v-prevent-reclick @click="save">Save</button>          → uses global default
 *   <a v-prevent-reclick="500" @click="submit">Submit</a>          → 500 ms override
 *
 * Uses capture phase so the block runs before Vue's @click handler on the same element.
 */
/** Fallback if Vue.config.preventReclickDefaultMs is not set */
export var DEFAULT_PREVENT_RECLICK_MS = 2000;

function getDefaultCooldownMs(Vue) {
    var cfg = Vue && Vue.config && Vue.config.preventReclickDefaultMs;
    if (typeof cfg === 'number' && cfg >= 0) {
        return cfg;
    }
    return DEFAULT_PREVENT_RECLICK_MS;
}

function resolveCooldown(binding, Vue) {
    if (typeof binding.value === 'number' && binding.value >= 0) {
        return binding.value;
    }
    return getDefaultCooldownMs(Vue);
}

export function registerPreventReclickDirective(Vue) {
    Vue.directive('prevent-reclick', {
        bind(el, binding) {
            el.__preventReclickCooldown = resolveCooldown(binding, Vue);

            var lastClickTime = 0;

            var handler = function (e) {
                var cooldownMs = el.__preventReclickCooldown;
                if (cooldownMs === 0) {
                    return;
                }
                var now = Date.now();
                if (now - lastClickTime < cooldownMs) {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    e.stopPropagation();
                    return false;
                }
                lastClickTime = now;
            };

            el.addEventListener('click', handler, true);
            el.__preventReclickHandler = handler;
        },
        update(el, binding) {
            el.__preventReclickCooldown = resolveCooldown(binding, Vue);
        },
        unbind(el) {
            if (el.__preventReclickHandler) {
                el.removeEventListener('click', el.__preventReclickHandler, true);
                delete el.__preventReclickHandler;
                delete el.__preventReclickCooldown;
            }
        }
    });
}
